import{mapWithConcurrency}from"#shared/map-with-concurrency.js";async function releaseOrphanedLocalSteps(e,t){await mapWithConcurrency(t,8,async t=>{try{await e.releaseOrphanedSteps(t)}catch(e){console.warn(`[eve] Failed to release orphaned steps of workflow run ${t}:`,e)}})}function localRecoveryMessage(e){return{runId:e.runId,...typeof e.specVersion==`number`&&{runSpecVersion:e.specVersion},recovery:!0}}export{localRecoveryMessage,releaseOrphanedLocalSteps};